/// Quote of the local calendar day.
export function quoteOfDay(date: Date): DailyQuote {
  const yearStart = new Date(date.getFullYear(), 0, 0);
  const dayOfYear = Math.floor((date.getTime() - yearStart.getTime()) / 86_400_000);
  return QUOTES[(dayOfYear - 1) % QUOTES.length];
}

export function dailyQuote(lang: Language, date: Date): { text: string; author: string } {
  const quote = quoteOfDay(date);
  return { text: lang === "vi" ? quote.vi : quote.en, author: quote.author };
}
